import{_ as t}from"./chunks/clee-api-in-drupal.Wq3GJ01c.js";import{_ as r,c as o,o as a,ae as s}from"./chunks/framework.DBgX5bsf.js";const v=JSON.parse('{"title":"Gestion des methodes de paiements","description":"","frontmatter":{},"headers":[],"relativePath":"fr/docs/commerce/paiements.md","filePath":"fr/docs/commerce/paiements.md"}'),i={name:"fr/docs/commerce/paiements.md"};function n(c,e,p,l,u,d){return a(),o("div",null,e[0]||(e[0]=[s('<h1 id="gestion-des-methodes-de-paiements" tabindex="-1">Gestion des methodes de paiements <a class="header-anchor" href="#gestion-des-methodes-de-paiements" aria-label="Permalink to &quot;Gestion des methodes de paiements&quot;">​</a></h1><p>Nous vous proposons 2 methodes de paiements, le paiement par carte bancaire et le paiement via Paypal. Ces deux methodes sont les plus utilisées.</p><h2 id="paiement-par-carte-bancaire" tabindex="-1">Paiement par carte bancaire <a class="header-anchor" href="#paiement-par-carte-bancaire" aria-label="Permalink to &quot;Paiement par carte bancaire&quot;">​</a></h2><p>Pour ce mode de paiement, nous utilisons <strong>Stripe</strong> pour effectuer les transactions. Stripe est une plateforme de paiement en ligne qui permet aux entreprises de toutes tailles d&#39;accepter les paiements en ligne, notamment par carte bancaire, en toute sécurité.</p><h3 id="creez-un-compte-stripe" tabindex="-1">Creez un compte stripe <a class="header-anchor" href="#creez-un-compte-stripe" aria-label="Permalink to &quot;Creez un compte stripe&quot;">​</a></h3><p>Pour commencer, vous devez creer un compte <strong>Stripe</strong>. Pour cela, rendez-vous sur <a href="https://stripe.com/fr" target="_blank" rel="noreferrer">stripe.com</a> et suivez les instructions.</p><h4 id="configurer-votre-compte" tabindex="-1">Configurer votre compte <a class="header-anchor" href="#configurer-votre-compte" aria-label="Permalink to &quot;Configurer votre compte&quot;">​</a></h4><ul><li><strong>Complétez votre profil</strong> : Après la validation, Stripe vous demandera de fournir des informations supplémentaires sur votre entreprise (adresse, type d&#39;activité, etc.).</li><li><strong>Ajoutez un compte bancaire</strong> : Pour recevoir des paiements, vous devez ajouter un compte bancaire où Stripe pourra transférer les fonds.</li></ul><h4 id="recuperer-les-cles-d-api" tabindex="-1">Récupérer les clés d&#39;API <a class="header-anchor" href="#recuperer-les-cles-d-api" aria-label="Permalink to &quot;Récupérer les clés d&#39;API&quot;">​</a></h4><ul><li><p><strong>Accédez au tableau de bord</strong> : Une fois votre compte configuré, connectez-vous à votre tableau de bord Stripe.</p></li><li><p><strong>Allez dans les paramètres de développeur</strong> : Dans le menu de gauche, cliquez sur &quot;Developers&quot; (Développeurs).</p></li><li><p><strong>Clés API</strong> : Sous l&#39;onglet &quot;API keys&quot;, vous trouverez vos clés API :</p><ul><li><p>Clé publique (<em>Publishable key</em>)</p></li><li><p>Clé secrète (<em>Secret key</em>)</p></li></ul></li></ul><h4 id="ajouter-vos-cles-d-api-a-votre-boutique" tabindex="-1">Ajouter vos clés d&#39;API à votre boutique <a class="header-anchor" href="#ajouter-vos-cles-d-api-a-votre-boutique" aria-label="Permalink to &quot;Ajouter vos clés d&#39;API à votre boutique&quot;">​</a></h4><p>Dans votre site drupal, aller sur <code>commerce</code> &gt; <code>configuration</code> &gt; <code>commerce</code> &gt; <code>payment gateways</code> &gt; <code>Carte bancaire (stripe)</code> et ajoutez vos clés d&#39;API.</p><p><img src="'+t+'" alt="stripe"></p>',13)]))}const f=r(i,[["render",n]]);export{v as __pageData,f as default};
